{
  "name": "@hornhoof/node",
  "description": "The Hornhoof node: runs a company's agents and checks on one machine and keeps it connected to the server.",
  "license": "MIT",
  "author": "Ivan Korol",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/invariant0x/hornhoof.git",
    "directory": "apps/node"
  },
  "version": "0.34.0",
  "private": true,
  "type": "module",
  "bin": {
    "hornhoof-node": "dist/main.js"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "pretest": "npm run build -w @hornhoof/protocol && npm run build",
    "test": "vitest run",
    "lint:part": "eslint"
  },
  "dependencies": {
    "@hornhoof/protocol": "*",
    "age-encryption": "0.3.1",
    "jpeg-js": "0.4.4",
    "pngjs": "7.0.0",
    "saxes": "6.0.0",
    "typescript": "^5.9.3",
    "ws": "^8.22.0",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@types/node": "^22.20.5",
    "@types/pngjs": "6.0.5",
    "@types/ws": "^8.18.2",
    "@vitest/coverage-v8": "^5.0.5",
    "vitest": "^5.0.5"
  }
}

