{
  "name": "@hornhoof/protocol",
  "description": "Types and messages shared by the Hornhoof server, node and web app.",
  "license": "MIT",
  "author": "Ivan Korol",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/invariant0x/hornhoof.git",
    "directory": "packages/protocol"
  },
  "private": true,
  "type": "module",
  "exports": {
    "./program-operator": {
      "types": "./dist/program-operator.d.ts",
      "default": "./dist/program-operator.js"
    },
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./catalog": {
      "types": "./dist/catalog.d.ts",
      "default": "./dist/catalog.js"
    },
    "./approval-policy": {
      "types": "./dist/approval-policy.d.ts",
      "default": "./dist/approval-policy.js"
    },
    "./efforts": {
      "types": "./dist/efforts.d.ts",
      "default": "./dist/efforts.js"
    },
    "./link": {
      "types": "./dist/link.d.ts",
      "default": "./dist/link.js"
    },
    "./map": {
      "types": "./dist/map.d.ts",
      "default": "./dist/map.js"
    },
    "./pipeline-report": {
      "types": "./dist/pipeline-report.d.ts",
      "default": "./dist/pipeline-report.js"
    },
    "./signin": {
      "types": "./dist/signin.d.ts",
      "default": "./dist/signin.js"
    },
    "./waits": {
      "types": "./dist/waits.d.ts",
      "default": "./dist/waits.js"
    },
    "./echelons": {
      "types": "./dist/echelons.d.ts",
      "default": "./dist/echelons.js"
    },
    "./redaction": {
      "types": "./dist/redaction.d.ts",
      "default": "./dist/redaction.js"
    }
  },
  "types": "./dist/index.d.ts",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "vitest run",
    "lint:part": "eslint"
  },
  "dependencies": {
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@vitest/coverage-v8": "^5.0.5",
    "typescript": "^5.9.3",
    "vitest": "^5.0.5"
  },
  "version": "0.34.0"
}
